class CosmosQuery
{
    // EF Core 9 breaking change #3: synchronous I/O (ToList, First, Single, etc.)
    // is no longer supported by the Cosmos provider. All queries must use async APIs.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still references c.Discriminator (preserved via
        // HasDiscriminator("Discriminator") in OnModelCreating).
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";
        // Migrated from sync .ToList() to async .ToListAsync()
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

