using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // BREAKING CHANGE #1 — Discriminator property renamed.
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Existing 500K documents use "Discriminator", and direct SQL queries
            // reference c.Discriminator. Preserve the old property name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE #2 — id value format changed.
            // EF Core 8: id = "Product|123"  (EntityType|Key)
            // EF Core 9: id = "123"          (bare key only)
            // Existing documents use the old format. Without this, EF Core 9 cannot
            // find, update, or delete any of the 500K existing documents.
            // Preserve the old format by generating it explicitly.
            entity.Property<string>("__id")
                  .HasValueGeneratorFactory<LegacyCosmosIdGeneratorFactory>();
        });
    }
